mapper.select:
select card_image.id, user.id as user_id, user.name as user_name, card_image.url, label.name as label, card_image.like_count as like_count, card_image.comment_count as comment_count, card_image.create_time as create_time from card_image left join label on card_image.label_id = label.id left join user on card_image.user_id = user.id
label.id = #{labelId}
limit #{page}, #{pageSize}
